"""Integer primal/dual geometry generated by one primitive transfer law.

For a connected slot-transfer graph G and a zero-sum relation displacement x,
the primitive word norm equals both

1. the minimum number of unit edge transfers realizing x;
2. the maximum response sum <x,phi> over integer potentials satisfying
   |phi_i-phi_j|<=1 on every primitive edge.

This is the integer network min-cost-flow / Lipschitz-potential duality.  Total
unimodularity of graph incidence gives integral optima.  In Enterprise Math the
causal interpretation is primary: the same primitive operation law generates a
transport distance and its dual unit-response precision domain.
"""

from __future__ import annotations

from itertools import product

from .causal_basis_envelope_geometry import graph_metric_via_tree_envelope
from .causal_transfer_graph_geometry import Edge, Vector, transfer_components


def _adjacency(slot_count: int, edges: tuple[Edge, ...]) -> dict[int, set[int]]:
    adjacency = {slot: set() for slot in range(slot_count)}
    for left, right in edges:
        if left == right or any(index < 0 or index >= slot_count for index in (left, right)):
            raise ValueError("edges must contain distinct valid slots")
        adjacency[left].add(right)
        adjacency[right].add(left)
    return adjacency


def graph_diameter(slot_count: int, edges: tuple[Edge, ...]) -> int:
    if len(transfer_components(slot_count, edges)) != 1:
        raise ValueError("dual response potentials require a connected graph")
    adjacency = _adjacency(slot_count, edges)
    maximum = 0
    for source in range(slot_count):
        distance = {source: 0}
        queue = [source]
        for current in queue:
            for nxt in adjacency[current]:
                if nxt in distance:
                    continue
                distance[nxt] = distance[current] + 1
                queue.append(nxt)
        maximum = max(maximum, max(distance.values()))
    return maximum


def is_unit_response_potential(potential: Vector, edges: tuple[Edge, ...]) -> bool:
    if not potential or any(isinstance(value, bool) or not isinstance(value, int) for value in potential):
        raise ValueError("potential must be a non-empty integer tuple")
    return all(abs(potential[left] - potential[right]) <= 1 for left, right in edges)


def integer_unit_response_potentials(
    slot_count: int,
    edges: tuple[Edge, ...],
    anchor: int = 0,
) -> tuple[Vector, ...]:
    """Enumerate anchored integer 1-Lipschitz potentials; exact for small research graphs."""
    if isinstance(anchor, bool) or not isinstance(anchor, int) or not (0 <= anchor < slot_count):
        raise ValueError("anchor must be a valid slot")
    diameter = graph_diameter(slot_count, edges)
    potentials = []
    for values in product(range(-diameter, diameter + 1), repeat=slot_count - 1):
        potential = []
        cursor = 0
        for slot in range(slot_count):
            if slot == anchor:
                potential.append(0)
            else:
                potential.append(values[cursor])
                cursor += 1
        candidate = tuple(potential)
        if is_unit_response_potential(candidate, edges):
            potentials.append(candidate)
    return tuple(potentials)


def dual_response_value(displacement: Vector, potential: Vector) -> int:
    if len(displacement) != len(potential):
        raise ValueError("displacement and potential must have equal slot counts")
    return sum(value * response for value, response in zip(displacement, potential))


def maximum_unit_response(
    displacement: Vector,
    edges: tuple[Edge, ...],
    anchor: int = 0,
) -> int:
    if not displacement or sum(displacement) != 0:
        raise ValueError("displacement must be a nonempty zero-sum integer vector")
    potentials = integer_unit_response_potentials(len(displacement), edges, anchor)
    return max(dual_response_value(displacement, potential) for potential in potentials)


def primal_transfer_distance(displacement: Vector, edges: tuple[Edge, ...]) -> int:
    origin = (0,) * len(displacement)
    return graph_metric_via_tree_envelope(origin, displacement, edges)


def integer_transfer_response_duality(
    displacement: Vector,
    edges: tuple[Edge, ...],
) -> bool:
    return primal_transfer_distance(displacement, edges) == maximum_unit_response(displacement, edges)


def pair_probe_range_bound(slot_count: int, edges: tuple[Edge, ...], left: int, right: int) -> int:
    """Maximum |phi_left-phi_right| across unit-response probes equals graph distance."""
    if any(index < 0 or index >= slot_count for index in (left, right)):
        raise ValueError("slot index outside range")
    potentials = integer_unit_response_potentials(slot_count, edges, anchor=0)
    return max(abs(potential[left] - potential[right]) for potential in potentials)
